const assert = require('assert');
const fs = require('fs');

module.exports = function () {
  const mode = process.env.TOV_STDIO_SIGWINCH;
  const stdout = process.stdout;
  const stderr = process.stderr;
  const streams = [];
  if (mode !== 'stderr') streams.push(stdout);
  if (mode !== 'stdout') streams.push(stderr);
  for (const stream of streams) {
    assert.strictEqual(stream.isTTY, true);
    assert.deepStrictEqual(stream.getWindowSize(), [80, 24]);
  }
  if (mode === 'exit') return;
  const plain = mode === 'stdout' ? stderr : mode === 'stderr' ? stdout : null;
  if (plain) assert.notStrictEqual(plain.isTTY, true);

  const counts = streams.map(() => 0);
  streams.forEach((stream, i) => stream.on('resize', () => { counts[i]++; }));
  // External harness deadline: keeps the fixture alive until the final signal acknowledgement.
  const deadline = setTimeout(() => assert.fail('PTY harness did not finish'), 15000);
  let signals = 0;
  const acknowledge = (line) => fs.writeSync(Number(process.env.TOV_SIGWINCH_ACK_FD), line + '\n');
  // Access to both streams above must register their refresh before this user listener.
  process.on('SIGWINCH', () => {
    const expected = signals === 0 ? [101, 37] : [119, 43];
    const expectedCount = signals === 0 ? 1 : 2;
    for (let i = 0; i < streams.length; i++) {
      assert.deepStrictEqual([streams[i].columns, streams[i].rows], expected);
      assert.strictEqual(counts[i], expectedCount);
    }
    signals++;
    if (signals === 3) clearTimeout(deadline);
    acknowledge('SIGNAL ' + signals);
  });
  acknowledge('READY');
};
